#include "model_params.h"

#include "andon_model.h"  // generated by andon.export_c into firmware/model (not in git)

_Static_assert(ANDON_N_FFT == LOGMEL_N_FFT, "the C front end is built for a 1024-point FFT");
_Static_assert(ANDON_N_CONV == 4, "model_params.c lists four conv layers");
_Static_assert(ANDON_N_CLASSES <= MODEL_MAX_CLASSES, "raise MODEL_MAX_CLASSES");

const mel_bank_t andon_mel_bank = {
    .n_mels = ANDON_N_MELS,
    .start = andon_mel_start,
    .len = andon_mel_len,
    .weight = andon_mel_weight,
};

#define CONV(i)                                                                      \
    {                                                                                \
        .in_ch = ANDON_CONV##i##_IN, .out_ch = ANDON_CONV##i##_OUT,                  \
        .stride = ANDON_CONV##i##_STRIDE, .pool_before = ANDON_CONV##i##_POOL_BEFORE, \
        .out_zero = ANDON_CONV##i##_OUT_ZERO, .weight = andon_conv##i##_weight,      \
        .bias = andon_conv##i##_bias, .mult = andon_conv##i##_mult,                  \
        .shift = andon_conv##i##_shift,                                              \
    }

const model_t andon_model = {
    .n_mels = ANDON_N_MELS,
    .patch_frames = ANDON_PATCH_FRAMES,
    .n_classes = ANDON_N_CLASSES,
    .n_conv = ANDON_N_CONV,
    .pool_size = ANDON_POOL_SIZE,
    .band_mean = andon_band_mean,
    .band_std = andon_band_std,
    .input_scale = andon_input_scale,
    .input_zero = andon_input_zero,
    .conv = {CONV(0), CONV(1), CONV(2), CONV(3)},
    .head_weight = andon_head_weight,
    .head_bias = andon_head_bias,
    .head_scale = andon_head_scale,
};
